  if (dlg?.isOpen) { try { await sdk.clickDialogByText(/continue/i);}catch{} await sdk.waitForTicks(1); continue; }
  const before = sdk.countInventoryItems(/^raw (tuna|lobster)$/i);
  const spots = sdk.getNearbyNpcs().filter(n=>/Fishing spot/i.test(n.name) && n.optionsWithIndex.some(o=>/^cage$|^harpoon$/i.test(o.text)));
  const spot = spots[Math.floor(Math.random()*spots.length)];
  if (!spot) { await sdk.waitForTicks(2); continue; }
  const cageOpt = spot.optionsWithIndex.find(o=>/^cage$/i.test(o.text));
  const harpOpt = spot.optionsWithIndex.find(o=>/^harpoon$/i.test(o.text));
  const opt = Math.random()<0.5 && cageOpt ? cageOpt : (harpOpt || cageOpt);
  await sdk.sendInteractNpc(spot.index, opt.opIndex);
  try { await sdk.waitForCondition(()=> sdk.countInventoryItems(/^raw (tuna|lobster)$/i) > before, 8000); } catch {}
  const after = sdk.countInventoryItems(/^raw (tuna|lobster)$/i);
  if (after > before) catches++;
  console.log('catches', catches, 'raw', after);
}
